bility":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"tokenId","type":"uint256"}],"name":"settle","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"tokenId","type":"uint256"}],"name":"settled","outputs":[{"internalType":"bool","name":"","type":"bool"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"startedAt","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"tokenId","type":"uint256"}],"name":"stashHandle","outputs":[{"internalType":"bytes32","name":"","type":"bytes32"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"vetMultiplier","outputs":[{"internalType":"uint8","name":"","type":"uint8"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"welcomeBag","outputs":[{"internalType":"uint64","name":"","type":"uint64"}],"stateMutability":"view","type":"function"}],"devdoc":{"details":"Design notes.  1. Every croquette the Pantry holds belongs to exactly one encrypted bucket: the reserve     (welcome bags and purrs), a box's stash, or the burnt pile. Buckets only move between     each other or out to a player, so the Pantry's cCROQ balance always covers them.  2. NOBODY is allowed on a stash, the reserve or the burnt pile, holder and deployer     included. FHE.allow grants are permanent, so a stash readable by its holder would stay     readable by every past holder after a sale. The only amounts a player can decrypt are     their own transfers, which cCROQ grants them.  3. "Burnt" means locked here for good: no function moves the burnt pile. Real burning would     strand the same ERC-20 inside the wrapper anyway, at a higher FHE cost.  4. A feeder who holds less than they offer moves 0. The meal still counts, still costs     gas, and nothing on-chain tells it apart from a real one.  HCU per function (protocol limit 20,000,000 per transaction), measured in tests:    feed            ~2,152,000   confidential transferFrom, mul + div for the burn    claim           ~680,000 per purring box, ~6.8M for the 10-box maximum                    0 once the purr has halved to nothing    settle          0 (never fed), ~162,000 (ghost), ~586,000 (alive, asleep),                    ~1,990,000 (quantum: mul + div for the half)","errors":{"SafeERC20FailedOperation(address)":[{"details":"An operation with an ERC-20 token failed."}]},"kind":"dev","methods":{"claim(uint256[])":{"details":"One encrypted draw per box, multiplied by the days owed. Boxes with nothing owed      are skipped; a claim where every box is skipped reverts."},"feed(uint256,bytes32,bytes)":{"params":{"amount":"encrypted amount, made for this contract and the caller with the Relayer SDK","inputProof":"the proof that comes with it"}}},"title":"Pantry","version":1},"userdoc":{"errors":{"SenderNotAllowedToUseHandle(bytes32,address)":[{"notice":"Returned if the sender is not allowed to use the handle."}],"ZamaProtocolUnsupported()":[{"notice":"Returned if the Zama protocol is not supported on the current chain"}]},"kind":"user","methods":{"claim(uint256[])":{"notice":"Collects, for each listed box the caller holds: its welcome bag the first time,         then its purr for every whole day since its last claim (up to `purrMaxDays`).         Everything arrives as one encrypted cCROQ transfer that only the caller can read."},"feed(uint256,bytes32,bytes)":{"notice":"Serves a sealed box an encrypted amount of the caller's cCROQ. A share is burnt,         the rest joins the box's stash. The caller must have made the Pantry an operator         on cCROQ (`setOperator`)."},"fund(uint64)":{"notice":"Adds plain CROQ to the game reserve. The caller must have approved the Pantry.         Public amount: it moves as a plain ERC-20 before being wrapped."},"halvings()":{"notice":"How many times the purr has halved so far."},"lastPurr(uint256)":{"notice":"When a box last purred. Zero until its welcome bag is collected."},"meals(uint256)":{"notice":"How many meals each box was served. Public; what they held is not."},"nextClaimAt(uint256)":{"notice":"When `tokenId` can next claim something: now for a box that never claimed."},"payoutBps(uint8)":{"notice":"Share of the stash a cat in `state` pays its holder, in basis points."},"settle(uint256)":{"notice":"Settles an opened box's stash. Anyone may call it, once, after DoNotOpen has         finalized the reveal. Pays the holder of the moment their share and burns the rest."},"stashHandle(uint256)":{"notice":"Handle of a box's encrypted stash. A handle is an identifier, not the value:         nobody is allowed to decrypt it."}},"notice":"Runs the croquette economy next to DO NOT OPEN, without touching it.         Feed a sealed box cCROQ and the croquettes pile up in its encrypted stash. Nobody can         read or withdraw a stash while the box is sealed. Once the box is opened, the cat         decides: the living and the sleeping pay the stash to the holder, a ghost burns it         all, a quantum cat burns half. Holders also collect a welcome bag and a daily purr.","version":1}},"settings":{"compilationTarget":{"contracts/Pantry.sol":"Pantry"},"evmVersion":"cancun","libraries":{},"metadata":{"bytecodeHash":"none","useLiteralContent":true},"optimizer":{"enabled":true,"runs":800},"remappings":[]},"sources":{"@fhevm/solidity/config/ZamaConfig.sol":{"content":"// SPDX-License-Identifier: BSD-3-Clause-Clear
pragma solidity ^0.8.24;

import {FHE} from "@fhevm/solidity/lib/FHE.sol";
import {CoprocessorConfig} from "@fhevm/solidity/lib/Impl.sol";

/**
 * @title   ZamaConfig.
 * @notice  This library returns the FHEVM config for different networks
 *          with the contract addresses for (1) ACL, (2) CoprocessorAddress, (3) KMSVerifier,
 *          which are deployed & maintained by Zama.
 */
library ZamaConfig {
    /// @notice Returned if the Zama protocol is not supported on the current chain
    error ZamaProtocolUnsupported();

    function getEthereumCoprocessorConfig() internal view returns (CoprocessorConfig memory config) {
        if (block.chainid == 1) {
            config = _getEthereumConfig();
        } else if (block.chainid == 11155111) {
            config = _getSepoliaConfig();
        } else if (block.chainid == 31337) {
            config = _getLocalConfig();
        } else {
            revert ZamaProtocolUnsupported();
        }
    }

    function getConfidentialProtocolId() internal view returns (uint256) {
        if (block.chainid == 1) {
            return _getEthereumProtocolId();
        } else if (block.chainid == 11155111) {
            return _getSepoliaProtocolId();
        } else if (block.chainid == 31337) {
            return _getLocalProtocolId();
        }
        return 0;
    }

    /// @dev chainid == 1
    function _getEthereumProtocolId() private pure returns (uint256) {
        // Zama Ethereum protocol id is '1'
        return 1;
    }

    /// @dev chainid == 1
    function _getEthereumConfig() private pure returns (CoprocessorConfig memory) {
        // The addresses below are placeholders and should be replaced with actual addresses
        // once deployed on the Ethereum mainnet.
        return
            CoprocessorConfig({
                ACLAddress: 0xcA2E8f1F656CD25C01F05d0b243Ab1ecd4a8ffb6,
                CoprocessorAddress: 0xD82385dADa1ae3E969447f20A3164F6213100e75,
                KMSVerifierAddress: 0x77627828a55156b04Ac0DC0eb30467f1a552BB03
            });
    }

    /// @dev chainid == 11155111
    function _getSepoliaProtocolId() private pure returns (uint256) {
        // Zama Ethereum Sepolia protocol id is '10000 + Zama Ethereum protocol id'
        return 10001;
    }

    /// @dev chainid == 11155111
    function _getSepoliaConfig() private pure returns (CoprocessorConfig memory) {
        return
            CoprocessorConfig({
                ACLAddress: 0xf0Ffdc93b7E186bC2f8CB3dAA75D86d1930A433D,
                CoprocessorAddress: 0x92C920834Ec8941d2C77D188936E1f7A6f49c127,
                KMSVerifierAddress: 0xbE0E383937d564D7FF0BC3b46c51f0bF8d5C311A
            });
    }

    /// @dev chainid == 31337
    function _getLocalProtocolId() private pure returns (uint256) {
        return type(uint256).max;
    }

    function _getLocalConfig() private pure returns (CoprocessorConfig memory) {
        return
            CoprocessorConfig({
                ACLAddress: 0x50157CFfD6bBFA2DECe204a89ec419c23ef5755D,
                CoprocessorAddress: 0xe3a9105a3a932253A70F126eb1E3b589C643dD24,
                KMSVerifierAddress: 0x901F8942346f7AB3a01F6D7613119Bca447Bb030
            });
    }
}

/**
 * @title   ZamaEthereumConfig.
 * @dev     This contract can be inherited by a contract wishing to use the FHEVM contracts provided by Zama
 *          on the Ethereum (mainnet) network (chainId = 1) or Sepolia (testnet) network (chainId = 11155111).
 *          Other providers may offer similar contracts deployed at different addresses.
 *          If you wish to use them, you should rely on the instructions from these providers.
 */
abstract contract ZamaEthereumConfig {
    constructor() {
        FHE.setCoprocessor(ZamaConfig.getEthereumCoprocessorConfig());
    }

    function confidentialProtocolId() public view returns (uint256) {
        return ZamaConfig.getConfidentialProtocolId();
    }
}
